import {buildMountainBike} from './mountain-bike.mjs';
import {RIDE_ENTRY} from './downhill.mjs';
import {generatedMap} from './generated-materials.mjs';
import * as T from './vendor/three.module.js';
import {HOF} from './hof-layout.mjs';
import {POND_CAMP as C} from './alp-life.mjs';
import {createTerrainPath} from './terrain-path.mjs';
import {makeFlameMaterial} from './homestead-details.mjs';
export function createCozyProps(scene,height,colliders,interactive,animated,M,label){
 const root=new T.Group();root.userData.kind='cozy-working-alp';scene.add(root);const wood=M.wood,beam=M.beam,mat=(c,e={})=>new T.MeshStandardMaterial({color:c,roughness:1,...e});
 function mesh(geo,m,p=root){const o=new T.Mesh(geo,m);o.castShadow=o.receiveShadow=true;p.add(o);return o;}
 function box(w,h,d,m,x,y,z,p=root){const o=mesh(new T.BoxGeometry(w,h,d),m,p);o.position.set(x,y,z);return o;}
 function rod(a,b,r,m,p=root){const u=new T.Vector3(...a),v=new T.Vector3(...b),d=v.clone().sub(u),o=mesh(new T.CylinderGeometry(r*.83,r,d.length(),9),m,p);o.position.copy(u.add(v).multiplyScalar(.5));o.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),d.normalize());return o;}
 function cloth(color,tile=0){const map=generatedMap('cozy-materials',tile);if(map)return mat('#ffffff',{map,side:T.DoubleSide});const c=document.createElement('canvas');c.width=c.height=256;const ct=c.getContext('2d');ct.fillStyle=color;ct.fillRect(0,0,256,256);for(let i=0;i<256;i+=2){ct.strokeStyle=i%4?'#ffffff0b':'#211e1610';ct.beginPath();ct.moveTo(i,0);ct.lineTo(i,256);ct.stroke();ct.beginPath();ct.moveTo(0,i);ct.lineTo(256,i);ct.stroke();}const t=new T.CanvasTexture(c);t.colorSpace=T.SRGBColorSpace;t.wrapS=t.wrapT=T.RepeatWrapping;return mat('#ffffff',{map:t,side:T.DoubleSide});}
 // Open-sided hay store: no counter, shop sign or cash transaction.
 const shed=new T.Group();shed.position.set(HOF.kiosk.x,height(HOF.kiosk.x,HOF.kiosk.z),HOF.kiosk.z);shed.userData.kind='open-hay-shelter';root.add(shed);
 for(const x of[-1.65,1.65])for(const z of[-.75,.75]){box(.15,2.55,.15,beam,x,1.275,z,shed);colliders.push({type:'circle',x:HOF.kiosk.x+x,z:HOF.kiosk.z+z,r:.12});}for(const side of[-1,1]){rod([side*1.65,1.7,-.75],[side*.85,2.48,-.75],.06,wood,shed);rod([side*1.65,1.7,.75],[side*.85,2.48,.75],.06,wood,shed);}for(const z of[-.85,.85])box(3.65,.15,.13,beam,0,2.5,z,shed);for(const x of[-.9,0,.9])box(.12,.14,2.1,beam,x,2.6,0,shed);
 const roof=box(3.95,.13,2.45,M.shingle||wood,0,2.72,-.02,shed);roof.rotation.x=-.09;for(let i=0;i<10;i++)box(.29,.8,.07,wood,-1.5+i*.33,.4,-.83,shed);
 colliders.push({x:HOF.kiosk.x,z:HOF.kiosk.z-.38,w:2.6,d:.85});const hayCanvas=document.createElement('canvas');hayCanvas.width=512;hayCanvas.height=256;const hc=hayCanvas.getContext('2d');hc.fillStyle='#aa925c';hc.fillRect(0,0,512,256);for(let i=0;i<9000;i++){const x=(Math.sin(i*127.1)*.5+.5)*512,y=(Math.sin(i*311.7)*.5+.5)*256;hc.strokeStyle=['#d2bb7c','#b3a16b','#8e824e','#e0cb8a'][i%4];hc.lineWidth=i%3?.55:1.1;hc.beginPath();hc.moveTo(x,y);hc.lineTo(x+5+i%19,y+Math.sin(i)*3);hc.stroke();}const hayMap=generatedMap('hay')||new T.CanvasTexture(hayCanvas);hayMap.colorSpace=T.SRGBColorSpace;const hayMaterial=mat('#ffffff',{map:hayMap,bumpMap:hayMap,bumpScale:.018}),bales=[];
 for(let i=0;i<5;i++){const g=new T.Group();g.position.set(-1.04+(i%3)*1.02,.05+Math.floor(i/3)*.8,-.25);shed.add(g);g.userData.kind='stored-homegrown-hay-bale';const bale=mesh(new T.CylinderGeometry(.43,.46,.87,24,3),hayMaterial,g);bale.position.y=.43;bale.rotation.z=Math.PI/2;for(const side of[-1,1]){const tie=mesh(new T.TorusGeometry(.446,.014,5,30),beam,g);tie.rotation.y=Math.PI/2;tie.position.set(side*.27,.43,0);}bales.push(g);}
 const straw=new T.InstancedMesh(new T.CylinderGeometry(.004,.006,.28,4),mat('#c5b47e'),260),pose=new T.Object3D();for(let i=0;i<260;i++){pose.position.set(Math.sin(i*17.3)*1.35,.04,-.35+Math.cos(i*29.7)*.3);pose.rotation.set(Math.PI/2,i*2.39,0);pose.updateMatrix();straw.setMatrixAt(i,pose.matrix);}shed.add(straw);interactive.push({id:'hay-store',name:'Heu im Unterstand lagern & holen',...HOF.kiosk.entry,range:2.3,hayStorage:true});
 const sportGear=new T.Group();sportGear.userData.navigationId='ride-shelter';sportGear.userData.kind='bike-and-sled-shelter';root.add(sportGear);const bike=buildMountainBike();bike.position.set(-6.25,height(-6.25,-1.9),-1.9);sportGear.add(bike);

 const sled=new T.Group();sled.position.set(-3.8,height(-3.8,-2.1),-2.1);sportGear.add(sled);sled.userData.kind='swiss-wooden-sled';for(const x of[-.28,.28]){const curve=new T.CatmullRomCurve3([[x,.05,.7],[x,.05,-.7],[x,.12,-.95],[x,.33,-1.02]].map(v=>new T.Vector3(...v)));mesh(new T.TubeGeometry(curve,18,.035,8,false),beam,sled);for(const z of[-.45,.4])rod([x,.07,z],[x,.35,z],.025,wood,sled);}for(let j=0;j<5;j++)box(.6,.045,.19,wood,0,.36,-.5+j*.23,sled);interactive.push({id:'ride-shelter',name:'Bike & Schlitten · Abfahrt wählen',...RIDE_ENTRY,range:2,downhill:true});
 // One small shore-side clearing; earth, tent, timber seat and fire form a single place.
 const camp=new T.Group();camp.userData.kind='quiet-pond-clearing';root.add(camp);const clearing=createTerrainPath([[31,-8.8],[33,-10.4],[35.7,-11.8]],2.45,height,'#9d9277');clearing.userData.kind='camp-trampled-clearing';camp.add(clearing);
 const tent=new T.Group();tent.position.set(C.tent.x,height(C.tent.x,C.tent.z),C.tent.z);tent.rotation.y=-.55;tent.userData.kind='cozy-canvas-tent';camp.add(tent);const canvas=cloth('#b6a37b');
 for(const side of[-1,1]){const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute([0,1.8,-1.5,side*1.35,.05,-1.5,0,1.8,1.5,side*1.35,.05,1.5],3));geo.setAttribute('uv',new T.Float32BufferAttribute([0,0,1,0,0,1,1,1],2));geo.setIndex([0,1,2,1,3,2]);geo.computeVertexNormals();mesh(geo,canvas,tent);rod([side*1.35,.05,-1.5],[side*1.35,.05,1.5],.025,wood,tent);}
 box(2.5,.035,2.85,cloth('#5d6651'),0,.04,0,tent);box(.76,.12,1.9,cloth('#6a796c'),-.45,.13,-.2,tent);box(.65,.12,.38,cloth('#e5d7bc',1),-.45,.23,-1,tent);
 for(const z of[-1.5,1.5])rod([0,0,z],[0,1.8,z],.025,wood,tent);rod([0,1.8,-1.5],[0,1.8,1.5],.025,wood,tent);for(const side of[-1,1])for(const z of[-1.4,1.4]){rod([side*.65,1,z],[side*1.8,.03,z*1.2],.009,mat('#d5c4a2'),tent);rod([side*1.8,-.06,z*1.2],[side*1.8,.1,z*1.2],.02,wood,tent);}colliders.push({x:C.tent.x,z:C.tent.z,w:3.5,d:3.8});interactive.push({id:'tent-roast',x:C.tent.x-2.2,z:C.tent.z+.5,name:'Ein Abend am Lagerfeuer',range:2.2,cozyActivity:'roast'});
 const fire=new T.Group();fire.position.set(C.x,height(C.x,C.z),C.z);camp.add(fire);fire.userData.kind='cozy-stone-hearth';const stone=M.stone;for(let i=0;i<8;i++){const a=i*Math.PI/4,s=.15+(i%3)*.04,o=mesh(new T.IcosahedronGeometry(1,2),stone,fire);o.position.set(Math.cos(a)*.49,.08,Math.sin(a)*.49);o.scale.set(s*1.2,s*.65,s);o.rotation.y=a;}
 for(const a of[-.3,.3])rod([-.35,.1,a],[.35,.12,-a],.065,wood,fire);const flameMat=makeFlameMaterial(),flames=[];for(const a of[0,Math.PI/2]){const f=mesh(new T.PlaneGeometry(.32,.52),flameMat,fire);f.position.y=.34;f.rotation.y=a;flames.push(f);}const light=new T.PointLight('#ffd2a2',1,4);light.position.y=.7;fire.add(light);animated.push(t=>{flames.forEach(f=>f.scale.y=.88+Math.sin(t*4)*.1);light.intensity=.9+Math.sin(t*5)*.08;});colliders.push({type:'circle',x:C.x,z:C.z,r:.55});
 const seatX=33.8,seatZ=-7.7,y=height(seatX,seatZ);rod([seatX-1,y+.27,seatZ],[seatX+1,y+.27,seatZ],.22,wood,camp);colliders.push({x:seatX,z:seatZ,w:2.3,d:.55});const blanket=box(.85,.035,.42,cloth('#a86d50',3),seatX+.2,y+.48,seatZ,camp);blanket.rotation.y=.09;
 const kettle=mesh(new T.SphereGeometry(.17,20,14),mat('#574d3e',{metalness:.3,roughness:.65}),fire);kettle.scale.y=.75;kettle.position.set(.82,.14,.16);const handle=mesh(new T.TorusGeometry(.13,.015,6,20,Math.PI),wood,fire);handle.position.set(.82,.3,.16);interactive.push({id:'pond-camp',name:'Am See zur Ruhe kommen & übernachten',...C.entry,range:2.6,pondCamp:true});
 // A tidy, usable shore camp: timber pile, lantern and a small dry stone windbreak.
 const lantern=new T.Group();lantern.position.set(C.tent.x-.9,height(C.tent.x-.9,C.tent.z+1.2)+.28,C.tent.z+1.2);camp.add(lantern);lantern.userData.kind='camp-brass-lantern';box(.18,.05,.18,beam,0,-.18,0,lantern);box(.13,.28,.13,mat('#ffdf9d',{emissive:'#edab53',emissiveIntensity:.5}),0,0,0,lantern);box(.2,.045,.2,wood,0,.17,0,lantern);const lamp=new T.PointLight('#ffd69c',.8,3.5);lantern.add(lamp);
 for(let i=0;i<7;i++){const x=35.3+(i%3)*.2,z=-8.9,y=height(x,z);rod([x,y+.12+Math.floor(i/3)*.17,z-.4],[x+.12,y+.12+Math.floor(i/3)*.17,z+.4],.085,wood,camp);}
 for(let i=0;i<7;i++){const x=38.6+i*.12,z=-14.2+i*.17,y=height(x,z),o=mesh(new T.IcosahedronGeometry(1,2),M.stone,camp);o.position.set(x,y+.18,z);o.scale.set(.28+(i%3)*.08,.25,.28);o.userData.kind='camp-natural-rock-windbreak';}
 const mug=mesh(new T.CylinderGeometry(.075,.07,.12,18),mat('#d6ded2',{metalness:.12}),camp);mug.position.set(seatX-.6,y+.56,seatZ);const mugHandle=mesh(new T.TorusGeometry(.045,.012,6,16),wood,camp);mugHandle.position.set(seatX-.69,y+.56,seatZ);
 return{root,shed,camp,tent,sportGear,sync(s){bales.forEach((g,i)=>g.visible=i<Math.ceil(s.alpLife.hayStored/4));}};
}
